Lemma ap_ok_intro : forall (LS L : list (Z * Z)) (m : mem) data datad w h wpl fr KI KF LSP ks kfs lps ps pa parr ba barr,
  0 < w <= 20000 -> 0 < h <= 20000 -> wpl = (w * 8 + 31) / 32 -> 0 < 4 * (wpl * h) <= 0x4000000 ->
  (forall p n, In (p, n) L -> arange p n) -> (forall e, In e LS -> In e L) ->
  In (data, 4 * (wpl * h)) LS -> data mod 16 = 0 -> In (datad, 4 * (wpl * h)) L -> datad mod 16 = 0 ->
  0 < fr -> fr + 64 <= 2^47 -> (fr + 64 <= 2147446784 \/ 17594333495296 <= fr) -> 6746112 <= fr -> fr mod 64 = 0 ->
  chunk LS KI 1024 -> chunk LS KF 1024 -> kidx_ok 10 ks -> length kfs = 256%nat -> Forall kfr_le1 kfs -> ls_obj LS m LSP lps ps -> length ps = 10%nat ->
  pixa_objn LS m pa 10 parr ba barr ps -> Forall (fun e => p_w (pe_v e) = w /\ p_h (pe_v e) = h) ps ->
  (datad + 4 * (wpl * h) <= data \/ data + 4 * (wpl * h) <= datad) ->
  (fr + 64 <= datad \/ datad + 4 * (wpl * h) <= fr) ->
  (forall b k, In (b, k) LS -> datad + 4 * (wpl * h) <= b \/ b + k <= datad) ->
  ap_ok (mk_app data datad (4 * (wpl * h)) w h wpl (fr + 32) (fr + 48) KI KF LSP ks kfs lps ps).
